  r record; tid uuid; cue text;
begin
  for r in select id, title, regexp_replace(trim(title), '\s+', ' ', 'g') as nk from exercises
           where m ? regexp_replace(trim(title), '\s+', ' ', 'g') and video_url is null loop
    tid := null;
    select id into tid from exercises
      where regexp_replace(trim(title), '\s+', ' ', 'g') = m -> r.nk ->> 0 and id <> r.id
      order by (video_url is not null) desc, created_at limit 1;
    if tid is null then continue; end if;
    cue := nullif(m -> r.nk ->> 1, '');

    update workout_exercises set
      exercise_id = tid,
      notes = case when cue is null or coalesce(notes, '') ilike cue || '%' then notes
                   else cue || coalesce('. ' || nullif(trim(notes), ''), '') end
      where exercise_id = r.id;
    update workout_results set swapped_exercise_id = tid where swapped_exercise_id = r.id;
    insert into exercise_alternatives (exercise_id, alternative_id)
      select tid, alternative_id from exercise_alternatives where exercise_id = r.id and alternative_id <> tid
      on conflict do nothing;
    insert into exercise_alternatives (exercise_id, alternative_id)
      select exercise_id, tid from exercise_alternatives where alternative_id = r.id and exercise_id <> tid
      on conflict do nothing;
    delete from exercises where id = r.id;
  end loop;
end $$;

